geo<-list();matchrows<-list();alias<-c(Ohfunato='ofunato',Ohtsuchi='otsuchi',Iwaizumi='iwazumi','E-Matsushima'='higashimatsushima',Kamiamakusa='kamiamakusa',Ohzu='ozu',Kikuyoh='kikuyo',Shiiba='shiba')
for(i in seq_len(nrow(x))){r<-x[i,];nm<-r$join_name;note<-''
 if(r$region%in%c('Florida','Puerto Rico')){id<-which(us$STATEFP==ifelse(r$region=='Florida','12','72')&norm(us$NAME)==norm(nm));if(length(id)!=1)stop(paste("Ambiguous/unmatched source LGU:",nm,"event:",r$disaster,"matches",length(id)));g<-st_geometry(us)[id];gid<-as.character(us$GEOID[id]);gname<-as.character(us$NAME[id])}
 else if(nm%in%c('Sendai-Miyagino','Sendai-Wakabayashi','K-Chuo')){id<-match(nm,c('Sendai-Miyagino','Sendai-Wakabayashi','K-Chuo'));g<-ward[[id]];gid<-c('04102','04103','43101')[id];gname<-nm;note<-if(nm=='K-Chuo')'K-Chuo interpreted as Kumamoto Chuo ward for structure example'else'NII geoshape actual municipal ward geometry'}
 else{prefs<-switch(r$disaster,'Tohoku Tsunami'=c('Aomori','Iwate','Miyagi'),'Kumamoto Earthquake'=c('Kumamoto','Fukuoka','Oita','Miyazaki'),'Kinugawa Flood'=c('Ibaraki','Chiba'));if(r$disaster=='Kumamoto Earthquake'&&nm=='Misato')prefs<-'Kumamoto';if(r$disaster=='Kinugawa Flood'&&nm=='Yachiyo')prefs<-'Ibaraki';key<-if(nm%in%names(alias))alias[[nm]]else norm(nm);id<-which(jp$NAME_1%in%prefs & norm(jp$NAME_2)==key);if(length(id)!=1)stop(paste("Ambiguous/unmatched source LGU:",nm,"event:",r$disaster,"matches",length(id)));g<-st_geometry(jp)[id];gid<-as.character(jp$GID_2[id]);gname<-as.character(jp$NAME_2[id]);note<-if(nm%in%names(alias))'Explicit romanization alias; source name retained'else''}
 geo[[i]]<-g[[1]];matchrows[[i]]<-data.frame(source_name=r$source_name,geometry_id=gid,geometry_name=gname,geometry_note=note)
}
matched<-do.call(rbind,matchrows);stopifnot(nrow(matched)==200,!anyNA(matched$geometry_id));regions<-st_sf(cbind(x,matched[,setdiff(names(matched),'source_name')]),geometry=st_sfc(geo,crs=4326));cc<-st_coordinates(st_centroid(regions))
