# Nested schematic drawn as editable circles/ellipses and directed transitions.
ellipse<-function(cx,cy,rx,ry,n=100)data.frame(x=cx+rx*cos(seq(0,2*pi,length.out=n)),y=cy+ry*sin(seq(0,2*pi,length.out=n)))
poly<-list();k<-1
for(bi in 1:2){cy<-ifelse(bi==1,7.2,3.4);poly[[k]]<-transform(ellipse(3.8,cy,3.3,1.65),level='4',group=paste0('outer',bi));k<-k+1;for(ci in 1:2){cx<-ifelse(ci==1,2.2,5.3);poly[[k]]<-transform(ellipse(cx,cy,1.4,1.35),level='3',group=paste(bi,ci));k<-k+1;for(j in 1:2){poly[[k]]<-transform(ellipse(cx+ifelse(j==1,-.45,.48),cy+ifelse(j==1,.4,-.4),.5,.6),level='2',group=paste(bi,ci,j));k<-k+1}}}
polys<-do.call(rbind,poly);pts<-data.frame(x=rep(c(1.6,1.85,2.65,2.85,4.65,4.9,5.7,5.9),2),y=rep(c(7.65,7.42,6.7,6.95,7.7,7.43,6.7,6.95),2)-rep(c(0,3.8),each=8));tr<-data.frame(x=c(2.85,2.85,2.85),y=c(6.95,6.95,6.95),xe=c(1.6,5.9,2.85),ye=c(7.65,6.95,3.15),lev=c('2','3','4'))
