# V28: real Boston road and water layers; all movement and probability values are synthetic.
bbox<-st_bbox(c(xmin=-71.165,ymin=42.315,xmax=-71.035,ymax=42.42),crs=st_crs(4326));clip<-st_as_sfc(bbox)
readclip<-function(kind){d<-lapply(c('25017','25025'),function(co){file<-file.path(W,'geography',paste0('tl_2016_',co,'_',kind),paste0('tl_2016_',co,'_',kind,'.shp'));z<-st_read(file,quiet=TRUE)%>%st_transform(4326);z<-z[lengths(st_intersects(z,clip))>0,];z<-suppressWarnings(st_intersection(z,clip));st_sf(geometry=st_geometry(z))});do.call(rbind,d)}
roads<-suppressWarnings(st_collection_extract(readclip('roads'),'LINESTRING'));roads<-st_cast(roads,'MULTILINESTRING');water<-suppressWarnings(st_collection_extract(readclip('areawater'),'POLYGON'));water<-st_cast(st_make_valid(water),'MULTIPOLYGON');wet<-st_union(water);bostland<-st_difference(clip,wet);stopifnot(nrow(roads)>100,nrow(water)>1)
st_write(roads,file.path(PD,'asf28_boston_actual_roads_20261029.gpkg'),delete_dsn=TRUE,quiet=TRUE);st_write(water,file.path(PD,'asf28_boston_actual_water_20261029.gpkg'),delete_dsn=TRUE,quiet=TRUE)
primary<-data.frame(stop_id=1:4,lon=c(-71.129,-71.091,-71.107,-71.104),lat=c(42.396,42.353,42.361,42.374),type=c('Home','Work','Other 1','Other 2'),frequency=c(.36,.34,.04,.035))
extra<-data.frame(stop_id=5:18,lon=runif(14,bbox['xmin']+.01,bbox['xmax']-.005),lat=runif(14,bbox['ymin']+.005,bbox['ymax']-.004),type='Previous',frequency=runif(14,.003,.025));stays<-rbind(primary,extra);stays$frequency<-stays$frequency/sum(stays$frequency)
# Keep simulated point centers on real land; deterministically shift any point inside water to nearest land boundary plus epsilon.
ss<-st_as_sf(stays,coords=c('lon','lat'),crs=4326);bad<-lengths(st_intersects(ss,wet))>0
if(any(bad)){ln<-st_nearest_points(ss[bad,],bostland);for(i in seq_along(ln)){co<-st_coordinates(ln[i]);j<-which(bad)[i];stays$lon[j]<-tail(co[,1],1)-.00015;stays$lat[j]<-tail(co[,2],1)+.00015}}
raw<-do.call(rbind,lapply(1:18,function(i)data.frame(lon=rnorm(round(6500*stays$frequency[i]),stays$lon[i],.005),lat=rnorm(round(6500*stays$frequency[i]),stays$lat[i],.004),stop_id=i)));inside<-lengths(st_intersects(st_as_sf(raw,coords=c('lon','lat'),crs=4326),bostland))>0;raw<-raw[inside,];raw$input_type<-'fixed-seed simulated geography-bound location trace';stays$input_type<-'fixed-seed simulated stay locations and normalized visit frequencies';stopifnot(abs(sum(stays$frequency)-1)<1e-12)
write.csv(raw,file.path(PD,'asf28_simulated_raw_trace_20261029.csv'),row.names=FALSE);write.csv(stays,file.path(PD,'asf28_simulated_stays_frequency_20261029.csv'),row.names=FALSE)
cols<-c(Home='#E6D627',Work='#326AA8','Other 1'='#DF3436','Other 2'='#72A638',Previous='#E7AE43')
city<-data.frame(lon=c(-71.109,-71.081,-71.084),lat=c(42.402,42.379,42.328),label=c('Somerville','Cambridge','Boston'))
base28<-function(){ggplot()+geom_sf(data=water,fill='#A4AAAC',colour=NA)+geom_sf(data=roads,colour='white',linewidth=.075)+coord_sf(xlim=c(bbox['xmin'],bbox['xmax']),ylim=c(bbox['ymin'],bbox['ymax']),expand=FALSE)+theme_void(base_family='Arial',base_size=7)+theme(panel.background=element_rect(fill='#E7E9EA',colour='#CDD0D2',linewidth=.2),plot.tag=element_text(size=8,face='bold'),plot.margin=margin(1,1,1,1),legend.position='none')}
orders<-list(c(1,3,4,2,1),c(1,2,3,1),c(1,2,3,4,1));days<-c('Monday','Friday','Wednesday');rows28<-list();odall<-list();timeall<-list();surfaceall<-list()
for(i in 1:3){ord<-orders[[i]];current<-stays[ord[-length(ord)],];currraw<-raw[raw$stop_id%in%ord,];currraw<-currraw[seq(1,nrow(currraw),length.out=min(80,nrow(currraw))),]
 a<-base28()+geom_point(data=raw,aes(lon,lat),colour='#7FAAD0',size=.17,alpha=.55)+geom_point(data=currraw,aes(lon,lat),colour='#934E9F',size=.55,alpha=.65)+geom_point(data=current,aes(lon,lat),shape=21,fill=NA,colour='#DE1C30',stroke=.6,size=2)+geom_text(data=city,aes(lon,lat,label=label),family='Arial',size=2.25,colour='#596266')+labs(tag=LETTERS[i])
 seg<-data.frame(lon=stays$lon[head(ord,-1)],lat=stays$lat[head(ord,-1)],xe=stays$lon[tail(ord,-1)],ye=stays$lat[tail(ord,-1)],destination=stays$type[tail(ord,-1)],day=days[i]);odall[[i]]<-seg
 seqdata<-stays[ord,];seqdata$seq<-0:(length(ord)-1);seqdata<-seqdata[!duplicated(seqdata$stop_id),]
 b<-base28()+geom_segment(data=seg,aes(lon,lat,xend=xe,yend=ye,colour=destination),linewidth=.55,arrow=arrow(length=unit(.8,'mm'),type='closed'))+scale_colour_manual(values=cols)+geom_point(data=current,aes(lon,lat,fill=type),colour='#1B2023',shape=21,size=2.3,stroke=.45)+scale_fill_manual(values=cols)+geom_text(data=seqdata,aes(lon,lat,label=seq),family='Arial',size=2.25,nudge_x=.0025,nudge_y=.0034)+labs(tag=LETTERS[i+3])
 times<-if(i==1)c(0,10.8,12,20.2,23,24)else if(i==2)c(0,12.5,13.2,22,24)else c(0,12.4,20.3,21.1,23.4,24);timeline<-data.frame(start=head(times,-1),end=tail(times,-1),type=stays$type[ord],day=days[i]);timeall[[i]]<-timeline
 tl<-ggplot(timeline)+geom_rect(aes(xmin=start,xmax=end,ymin=0,ymax=1,fill=type))+scale_fill_manual(values=cols)+scale_x_continuous(breaks=c(0,6,12,18,24),limits=c(-.5,24.5),expand=c(0,0))+coord_cartesian(ylim=c(0,1),expand=FALSE)+theme_classic(base_family='Arial',base_size=7)+theme(axis.title=element_blank(),axis.text.y=element_blank(),axis.ticks.y=element_blank(),axis.line.y=element_blank(),legend.position='none',plot.margin=margin(0,1,0,1),plot.title=element_text(size=7,hjust=.5))+ggtitle(paste(days[i],'(hours)'));b<-(b/tl)+plot_layout(heights=c(4.6,.65))
 links<-data.frame(lon=stays$lon[1],lat=stays$lat[1],xe=stays$lon[-1],ye=stays$lat[-1]);lab<-current;lab$label<-sprintf('%.1f%%',100*lab$frequency);lab$labelx<-lab$lon+c(Home=-.01,Work=.016,'Other 1'=-.02,'Other 2'=.008)[lab$type];lab$labely<-lab$lat+c(Home=.008,Work=-.005,'Other 1'=-.003,'Other 2'=.007)[lab$type]
 c<-base28()+geom_segment(data=links,aes(lon,lat,xend=xe,yend=ye),colour='#8F9495',linewidth=.2,alpha=.7)+geom_point(data=stays,aes(lon,lat,size=frequency,fill=type),shape=21,colour='#A9A7A4',stroke=.12,alpha=.6)+geom_segment(data=seg,aes(lon,lat,xend=xe,yend=ye),colour='#6D3888',linewidth=.4,arrow=arrow(length=unit(.8,'mm'),type='closed'))+geom_point(data=current,aes(lon,lat,size=frequency,fill=type),shape=21,colour='#303337',stroke=.3)+scale_size_area(max_size=5)+scale_fill_manual(values=cols)+geom_text(data=lab,aes(labelx,labely,label=label),family='Arial',size=2.25)+labs(tag=LETTERS[i+6])
 gridx<-expand.grid(lon=seq(bbox['xmin'],bbox['xmax'],length.out=70),lat=seq(bbox['ymin'],bbox['ymax'],length.out=70));onland<-lengths(st_intersects(st_as_sf(gridx,coords=c('lon','lat'),crs=4326),bostland))>0;gridx<-gridx[onland,];origin<-stays[i,];dd<-sqrt(((gridx$lon-origin$lon)*cos(origin$lat*pi/180))^2+(gridx$lat-origin$lat)^2);gridx$probability<-1/(.012+dd)^1.2;gridx$probability<-gridx$probability/sum(gridx$probability);gridx$height<-((gridx$probability-min(gridx$probability))/(max(gridx$probability)-min(gridx$probability)))^.7;gridx$rank_class<-cut(rank(gridx$probability,ties.method='first'),breaks=seq(0,nrow(gridx),length.out=13),labels=1:12,include.lowest=TRUE);gridx$origin<-c('Home','Work','Other')[i];gridx$input_type<-'illustrative inverse-distance probability surface; not fitted TimeGeo rank-EPR output';surfaceall[[i]]<-gridx
 project<-function(lon,lat,z=0){u<-(lon-bbox['xmin'])/diff(bbox[c('xmin','xmax')]);v<-(lat-bbox['ymin'])/diff(bbox[c('ymin','ymax')]);data.frame(x=.8*u+.26*v,y=.32*v+.65*z)};pc<-project(gridx$lon,gridx$lat,gridx$height);gridx$x<-pc$x;gridx$y<-pc$y
 roadcoords<-st_coordinates(roads);rc<-project(roadcoords[,1],roadcoords[,2]);rc$group<-interaction(roadcoords[,3],if(ncol(roadcoords)>=4)roadcoords[,4]else 1,drop=TRUE)
 waterpoly<-st_coordinates(water);wc<-project(waterpoly[,1],waterpoly[,2]);wc$group<-interaction(waterpoly[,3],waterpoly[,4],if(ncol(waterpoly)>=5)waterpoly[,5]else 1,drop=TRUE)
 originpc<-project(origin$lon,origin$lat);palette<-grDevices::colorRampPalette(c('#1D4E79','#35A3A3','#FFF1B0'),space='Lab')(12)
 d<-ggplot()+annotate('polygon',x=c(0,.8,1.06,.26),y=c(0,0,.32,.32),fill='#48494A')+geom_polygon(data=wc,aes(x,y,group=group),fill='#292B2D',colour=NA)+geom_path(data=rc,aes(x,y,group=group),colour='#8A8C8D',linewidth=.055)+geom_point(data=gridx,aes(x,y,colour=rank_class),size=.12,alpha=.85)+scale_colour_manual(values=palette)+annotate('segment',x=originpc$x,xend=originpc$x,y=originpc$y,yend=.99,colour=cols[c('Home','Work','Other 1')[i]],linewidth=.55)+annotate('text',x=originpc$x+.04,y=1.02,label=c('Home','Work','Other')[i],hjust=0,family='Arial',size=2.5,colour=c('#827700',cols['Work'],cols['Other 1'])[i])+coord_equal(xlim=c(0,1.15),ylim=c(0,1.08),expand=FALSE)+theme_void(base_family='Arial',base_size=7)+theme(legend.position='none',plot.margin=margin(1,1,1,1),plot.tag=element_text(size=8,face='bold'))+labs(tag=LETTERS[i+9])
 rows28[[i]]<-list(a,b,c,d)
}
