legplot<-function(type){p<-ggplot()+coord_cartesian(xlim=c(0,1),ylim=c(0,1),expand=FALSE)+theme_void(base_family='Arial',base_size=7)+theme(plot.margin=margin(1,1,1,1));if(type==1){p<-p+annotate('point',x=.06,y=c(.9,.72,.54),colour=c('#D62431','#934E9F','#7FAAD0'),size=c(2,1.4,.6),shape=c(1,16,16))+annotate('text',x=.14,y=c(.9,.72,.54,.29,.12),label=c('Extracted stays','Day records','All records','White: roads','Gray: water'),hjust=0,family='Arial',size=2.4)}
 if(type==2){p<-p+annotate('text',x=.02,y=.96,label='Stays / destination',hjust=0,family='Arial',size=2.4)+annotate('point',x=.06,y=c(.78,.6,.42,.24),fill=cols[1:4],colour='#252A2D',shape=21,size=2)+annotate('text',x=.14,y=c(.78,.6,.42,.24),label=names(cols)[1:4],hjust=0,family='Arial',size=2.4)+annotate('text',x=.02,y=.06,label='#: visiting order',hjust=0,family='Arial',size=2.4)}
 if(type==3){p<-p+annotate('text',x=.02,y=.96,label='Stay frequency',hjust=0,family='Arial',size=2.4)+annotate('point',x=.08,y=c(.72,.48,.28),fill=cols[c(1,2,5)],shape=21,colour='#34383A',size=c(5,4,1.5))+annotate('text',x=.2,y=c(.72,.48,.28),label=c('Home','Work','Previous'),hjust=0,family='Arial',size=2.4)+annotate('segment',x=.02,xend=.17,y=.1,yend=.1,colour='#6D3888',linewidth=.5,arrow=arrow(length=unit(1,'mm')))+annotate('text',x=.2,y=.1,label='Day OD link',hjust=0,family='Arial',size=2.4)}
 if(type==4){p<-p+annotate('text',x=.02,y=.98,label='Probability rank',hjust=0,family='Arial',size=2.4)+annotate('point',x=.07,y=seq(.87,.08,length.out=12),colour=palette,size=.9)+annotate('text',x=.16,y=seq(.87,.08,length.out=12),label=paste(1:12),hjust=0,family='Arial',size=2.3)};p}
